package store

import (
	"context"
	"errors"
	"time"
)

// SocialApp is one organization-managed OpenID Connect application. The client
// secret is stored sealed and is only opened by the sign-in flow.
type SocialApp struct {
	ID             string
	OrganizationID string
	Provider       string
	Brand          string
	ProviderID     string
	Name           string
	ClientID       string
	ClientSecret   []byte
	ServerURL      string
	CreatedAt      time.Time
}

// SocialAppInput carries a new application. ProviderID is generated by the
// caller so the callback URL is stable and unique.
type SocialAppInput struct {
	ProviderID   string
	Provider     string
	Brand        string
	Name         string
	ClientID     string
	ClientSecret []byte
	ServerURL    string
}

const socialAppColumns = `id::text,organization_id::text,provider,brand,provider_id,name,
	client_id,client_secret,server_url,created_at`

func scanSocialApp(row interface{ Scan(...any) error }) (SocialApp, error) {
	var app SocialApp
	if err := row.Scan(&app.ID, &app.OrganizationID, &app.Provider, &app.Brand, &app.ProviderID, &app.Name,
		&app.ClientID, &app.ClientSecret, &app.ServerURL, &app.CreatedAt); err != nil {
		return SocialApp{}, dbError(err)
	}
	return app, nil
}

// SocialApps lists one organization's applications.
func (s *Store) SocialApps(ctx context.Context, organizationID string) ([]SocialApp, error) {
	rows, err := s.pool.Query(ctx, "SELECT "+socialAppColumns+" FROM social_apps WHERE organization_id=$1::bigint ORDER BY id", organizationID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	apps := []SocialApp{}
	for rows.Next() {
		app, err := scanSocialApp(rows)
		if err != nil {
			return nil, err
		}
		apps = append(apps, app)
	}
	return apps, rows.Err()
}

// SocialApp reads one application inside its organization.
func (s *Store) SocialApp(ctx context.Context, organizationID, id string) (SocialApp, error) {
	return scanSocialApp(s.pool.QueryRow(ctx, "SELECT "+socialAppColumns+
		" FROM social_apps WHERE organization_id=$1::bigint AND id=$2::bigint", organizationID, id))
}

// SocialAppByProviderID resolves the public sign-in application identity.
func (s *Store) SocialAppByProviderID(ctx context.Context, providerID string) (SocialApp, error) {
	return scanSocialApp(s.pool.QueryRow(ctx, "SELECT "+socialAppColumns+" FROM social_apps WHERE provider_id=$1", providerID))
}

// PublicOrganizationApps resolves a workspace and its sign-in applications
// without requiring a session; the login page shows them to anonymous visitors.
func (s *Store) PublicOrganizationApps(ctx context.Context, slug string) (Organization, []SocialApp, error) {
	var org Organization
	if err := s.pool.QueryRow(ctx, "SELECT id::text,slug,name FROM organizations WHERE slug=$1", slug).
		Scan(&org.ID, &org.Slug, &org.Name); err != nil {
		return Organization{}, nil, dbError(err)
	}
	apps, err := s.SocialApps(ctx, org.ID)
	if err != nil {
		return Organization{}, nil, err
	}
	return org, apps, nil
}

// CreateSocialApp stores one application. A repeated provider identity is a
// conflict so the caller can generate another.
func (s *Store) CreateSocialApp(ctx context.Context, organizationID string, input SocialAppInput) (SocialApp, error) {
	if input.ProviderID == "" || input.Name == "" || input.ClientID == "" || len(input.ClientSecret) == 0 || input.ServerURL == "" {
		return SocialApp{}, errors.New("social application requires an identity, name, client and server URL")
	}
	return scanSocialApp(s.pool.QueryRow(ctx, `INSERT INTO social_apps(organization_id,provider,brand,provider_id,name,client_id,client_secret,server_url)
		VALUES($1::bigint,$2,$3,$4,$5,$6,$7,$8) RETURNING `+socialAppColumns,
		organizationID, input.Provider, input.Brand, input.ProviderID, input.Name, input.ClientID, input.ClientSecret, input.ServerURL))
}

// UpdateSocialApp replaces the mutable fields. A nil secret and an empty server
// URL keep the stored values.
func (s *Store) UpdateSocialApp(ctx context.Context, organizationID, id, name, clientID string, secret []byte, serverURL string) (SocialApp, error) {
	if name == "" || clientID == "" {
		return SocialApp{}, errors.New("social application requires a name and client ID")
	}
	return scanSocialApp(s.pool.QueryRow(ctx, `UPDATE social_apps SET name=$3,client_id=$4,
		client_secret=COALESCE($5,client_secret),server_url=CASE WHEN $6='' THEN server_url ELSE $6 END
		WHERE organization_id=$1::bigint AND id=$2::bigint RETURNING `+socialAppColumns,
		organizationID, id, name, clientID, secret, serverURL))
}

// DeleteSocialApp removes one application from its organization.
func (s *Store) DeleteSocialApp(ctx context.Context, organizationID, id string) error {
	tag, err := s.pool.Exec(ctx, "DELETE FROM social_apps WHERE organization_id=$1::bigint AND id=$2::bigint", organizationID, id)
	if err != nil {
		return err
	}
	if tag.RowsAffected() == 0 {
		return ErrNotFound
	}
	return nil
}
